import{_ as t}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as a,c as r,a as o}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const f=JSON.parse(`{"title":"What's new in v1.8.3","description":"Fix TUI layout: header/footer anchoring, viewport packing and narrow-terminal rendering","frontmatter":{"title":"What's new in v1.8.3","description":"Fix TUI layout: header/footer anchoring, viewport packing and narrow-terminal rendering","date":"2026-03-09T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-8-3.md","filePath":"blog/release-v1-8-3.md"}`),i={name:"blog/release-v1-8-3.md"};function n(s,e,l,h,c,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-s-new-in-github-code-search-v1-8-3" tabindex="-1">What&#39;s new in github-code-search v1.8.3 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-8-3" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.8.3&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.8.3" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.8.3</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="fix-header-no-longer-scrolls-off-screen" tabindex="-1">Fix: header no longer scrolls off screen <a class="header-anchor" href="#fix-header-no-longer-scrolls-off-screen" aria-label="Permalink to &quot;Fix: header no longer scrolls off screen&quot;">​</a></h3><p>In previous versions, scrolling down fast could push the <code>github-code-search</code> title bar and the column headers (<code>PATH</code>, <code>MATCH</code>) out of the visible area, leaving the TUI without any reference point. The header row is now anchored to the top of the viewport regardless of scroll offset.</p><h3 id="fix-footer-always-visible-at-the-bottom" tabindex="-1">Fix: footer always visible at the bottom <a class="header-anchor" href="#fix-footer-always-visible-at-the-bottom" aria-label="Permalink to &quot;Fix: footer always visible at the bottom&quot;">​</a></h3><p>The keyboard-shortcut bar at the bottom of the TUI could float up into the results area when the result list was shorter than the terminal height.<br> The viewport now fills any remaining vertical space with blank lines before rendering the footer, keeping it pinned to the last row.</p><h3 id="fix-correct-rendering-on-narrow-terminals-unicode-emoji-clipping" tabindex="-1">Fix: correct rendering on narrow terminals (Unicode / emoji clipping) <a class="header-anchor" href="#fix-correct-rendering-on-narrow-terminals-unicode-emoji-clipping" aria-label="Permalink to &quot;Fix: correct rendering on narrow terminals (Unicode / emoji clipping)&quot;">​</a></h3><p>The <code>clipAnsi</code> helper that truncates long lines to fit the terminal width was splitting multi-byte UTF-8 sequences such as emoji (e.g. <code>🔍</code>) at a raw byte boundary, producing garbled output or invisible characters on narrow terminals.<br> The helper now advances by full Unicode code points (<code>codePointAt</code>) and only clips between complete characters.</p><hr><h2 id="other-improvements" tabindex="-1">Other improvements <a class="header-anchor" href="#other-improvements" aria-label="Permalink to &quot;Other improvements&quot;">​</a></h2><ul><li><strong>Title badge contrast</strong> — the <code>github-code-search</code> badge in the header now renders in black on magenta instead of a low-contrast colour combination, making it readable on all common terminal themes.</li><li><strong>Viewport packing</strong> — <code>normalizeScrollOffset</code> prevents the scroll position from drifting past the last result, ensuring the bottom of the list always fills the screen.</li></ul><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or download the latest binary from <a href="https://github.com/fulll/github-code-search/releases/tag/v1.8.3" target="_blank" rel="noreferrer">GitHub Releases</a>.</p>',16)])])}const w=t(i,[["render",n]]);export{f as __pageData,w as default};
